  ('56d02eef-0a15-48e9-bd89-e2dc6d1909b8', 'd2e3f4a5-6b7c-4d32-9f12-2a3b4c5d6e32', null, 'topic'::public.curated_course_node_type, 'Theater Spaces and Stages', 'Students begin by learning how theater architecture shapes every technical choice. A stagehand who understands space can work safely, communicate clearly, and anticipate how scenery, lights, sound, performers, crew, and audience all fit together.', 0),
  ('6ffa821b-f07b-40f4-a404-c068cdd8569a', 'd2e3f4a5-6b7c-4d32-9f12-2a3b4c5d6e32', '56d02eef-0a15-48e9-bd89-e2dc6d1909b8', 'subtopic'::public.curated_course_node_type, 'Types of theater spaces', 'Why learn it: Students learn the vocabulary and working logic of common performance spaces so they can adapt technical choices to the room.', 0),
