update public.learning_paths
set
  title = 'Stagecraft / Technical Theater',
  goal = 'Stagecraft / Technical Theater',
  summary = 'This course introduces the tools, materials, vocabulary, safety practices, paperwork, and collaborative workflows of technical theater. Students learn how theater spaces function, how scenery and props are built and maintained, how lighting and sound systems are organized, how costumes and wardrobe operate backstage, how rigging and crew work require disciplined safety, and how technical drawings and production organization connect all departments from design through strike.',
  data = $stcrjson${"slug": "stagecraft-technical-theater", "title": "Stagecraft / Technical Theater", "description": "This course introduces the tools, materials, vocabulary, safety practices, paperwork, and collaborative workflows of technical theater. Students learn how theater spaces function, how scenery and props are built and maintained, how lighting and sound systems are organized, how costumes and wardrobe operate backstage, how rigging and crew work require disciplined safety, and how technical drawings and production organization connect all departments from design through strike.", "topics": [{"id": "56d02eef-0a15-48e9-bd89-e2dc6d1909b8", "type": "topic", "title": "Theater Spaces and Stages", "description": "Students begin by learning how theater architecture shapes every technical choice. A stagehand who understands space can work safely, communicate clearly, and anticipate how scenery, lights, sound, performers, crew, and audience all fit together.", "children": [{"id": "6ffa821b-f07b-40f4-a404-c068cdd8569a", "type": "subtopic", "title": "Types of theater spaces", "children": [{"id": "d69e38ee-bd06-48c9-bb52-2018f11af21a", "type": "concept", "title": "Proscenium"}, {"id": "6a4c8830-1879-4147-a748-de61904dbbed", "type": "concept", "title": "Thrust"}, {"id": "050380b9-a5f2-439d-ae73-a5d2c61d6126", "type": "concept", "title": "Arena"}, {"id": "f300008c-becd-4e5a-85b1-fb98c6bf543a", "type": "concept", "title": "Black box"}, {"id": "6d9cce9f-d7e3-4fa6-8986-67257f8ffcf2", "type": "concept", "title": "Found and site-specific spaces"}], "description": "Why learn it: Students learn the vocabulary and working logic of common performance spaces so they can adapt technical choices to the room."}, {"id": "3b9a4995-83e7-4163-9482-1096bbfa0015", "type": "subtopic", "title": "Stage geography", "children": [{"id": "1222a035-5422-47ea-a433-e8f5266b142c", "type": "concept", "title": "Upstage and downstage"}, {"id": "186fb58e-e69e-48e0-a879-039c0eb6fc32", "type": "concept", "title": "Stage left and stage right"}, {"id": "787d5fc3-7b9f-4ef3-8cc8-a637a1f36db3", "type": "concept", "title": "Center line"}, {"id": "1613befd-1827-4d5c-8381-e9c2ed9650f7", "type": "concept", "title": "Plaster line"}, {"id": "0abd86c3-5204-491c-abc0-37fba5fb32e4", "type": "concept", "title": "Wings and crossover"}], "description": "Why learn it: The goal is to move, measure, and communicate accurately using shared stage directions."}, {"id": "0b939165-8dac-4fba-929d-412cbb38622d", "type": "subtopic", "title": "Audience and backstage relationships", "children": [{"id": "bab75e69-5f54-4b38-b379-9283d0244d85", "type": "concept", "title": "Sightlines"}, {"id": "362e7a52-c99b-4d60-9f59-a38104084b49", "type": "concept", "title": "Masking"}, {"id": "c3d4202e-8161-4f06-82a2-20d46ab85fe2", "type": "concept", "title": "Backstage circulation"}, {"id": "12d2327d-9af1-4fc3-92fb-8dff67ef156b", "type": "concept", "title": "Front-of-house connection"}], "description": "Why learn it: Students see how sightlines, entrances, backstage traffic, and audience proximity affect production planning."}]}, {"id": "db39daf1-2370-481f-a9fd-f97dc887a306", "type": "topic", "title": "Shop Safety, Tools, and Materials", "description": "A stagecraft course treats safety as a creative foundation, not a checklist at the margins. Students learn how to use tools, materials, and shops responsibly before they build, paint, hang, focus, or run anything.", "children": [{"id": "aae9da73-eb8d-40ef-bb5a-a7d099c0b5fa", "type": "subtopic", "title": "Safety culture", "children": [{"id": "4005bf5e-e497-4636-ac9a-598a2d3ea476", "type": "concept", "title": "Personal protective equipment"}, {"id": "5cda8cc1-62fe-4d7c-ad7e-d7915e3818ed", "type": "concept", "title": "Housekeeping"}, {"id": "33fa8e76-716d-46cb-a464-ca10c7410924", "type": "concept", "title": "Tool authorization"}, {"id": "f7b91da6-388b-4d35-aa68-34efddce3362", "type": "concept", "title": "Stop-work authority"}], "description": "Why learn it: Students learn how shared habits prevent injuries and support professional trust."}, {"id": "ae73697d-339c-4f39-b376-b173f881cbd5", "type": "subtopic", "title": "Hand and power tools", "children": [{"id": "1a291d42-9f35-4157-bf92-c75d952cb59c", "type": "concept", "title": "Measuring tools"}, {"id": "450a9cf5-0223-442a-afc9-f2b526406198", "type": "concept", "title": "Saws and drills"}, {"id": "ef9c6ac0-2865-4e5b-be27-f7f794d3c120", "type": "concept", "title": "Fasteners"}, {"id": "f0f1a485-714b-4a23-8715-2eee376bb1b8", "type": "concept", "title": "Clamps"}, {"id": "366037dc-8650-4f76-9373-d1128cf8e273", "type": "concept", "title": "Maintenance and storage"}], "description": "Why learn it: Students identify common tools and learn what each tool is designed to do safely."}, {"id": "04451aba-7be7-4853-9f5c-492b1def9944", "type": "subtopic", "title": "Materials and shop math", "children": [{"id": "b271d3ee-8ed9-4172-989b-8b52fed6d685", "type": "concept", "title": "Lumber and sheet goods"}, {"id": "0abb85a6-921f-448a-b5da-ea3dc441fa01", "type": "concept", "title": "Hardware"}, {"id": "7be5009b-11f0-4ecd-a757-6e10382b3162", "type": "concept", "title": "Fractions and scale"}, {"id": "5f0c860d-1955-4b70-abf8-19d4cb3b744a", "type": "concept", "title": "Cut lists"}, {"id": "3f03b7f1-c946-4046-befb-37dd4d228a62", "type": "concept", "title": "Waste reduction"}], "description": "Why learn it: Students practice the math and material literacy needed to build accurately and efficiently."}]}, {"id": "5bc66c95-6f67-42ef-8a6f-5dd46c063fb8", "type": "topic", "title": "Scenery Construction", "description": "Scenic construction turns design ideas into stable, repeatable, performer-safe environments. Students learn basic theatrical building methods and the production thinking behind flats, platforms, wagons, stairs, and scenic units.", "children": [{"id": "bcb2da41-2af2-4097-8d09-f941f132af56", "type": "subtopic", "title": "Flats, platforms, and scenic units", "children": [{"id": "576ff664-4d6c-4183-80fb-1dc4b530a142", "type": "concept", "title": "Broadway and Hollywood flats"}, {"id": "c37e4bf6-f977-4f6e-b228-2dd0684dc10a", "type": "concept", "title": "Platforms"}, {"id": "c2cd28c2-5712-42b2-870e-27849cfcedb0", "type": "concept", "title": "Stairs"}, {"id": "b712d09e-2e9e-4526-84e9-982619f8c694", "type": "concept", "title": "Wagons"}, {"id": "b139e8f1-b36c-48ab-8daf-24cbdbf578bc", "type": "concept", "title": "Door and window units"}], "description": "Why learn it: Students learn the standard vocabulary of scenic construction and what different units are meant to accomplish."}, {"id": "445c3b5d-b33c-40dc-baf4-101dac0f8ab9", "type": "subtopic", "title": "Joinery and fastening", "children": [{"id": "860bc8c2-5092-4818-91c8-f2d9fcd52378", "type": "concept", "title": "Screws and bolts"}, {"id": "1e690628-26cb-493b-ab8a-0d6f5b161b0d", "type": "concept", "title": "Glue and bracing"}, {"id": "027fb346-3ff6-47cf-93c3-d09e32fd950c", "type": "concept", "title": "Casters"}, {"id": "adf08aea-78cd-42ac-b6c1-e8fe328c58e0", "type": "concept", "title": "Alignment"}, {"id": "1e45c919-e99c-4e2c-ba1a-0e610b0a5c05", "type": "concept", "title": "Labeling"}], "description": "Why learn it: Students practice how theatrical scenery is assembled, reinforced, labeled, and struck."}, {"id": "2b02321b-1871-4550-843a-8b9907d503d8", "type": "subtopic", "title": "Load, stability, and performer safety", "children": [{"id": "0ebd40fd-941e-4e30-a11d-3a8a6d45fc6f", "type": "concept", "title": "Live load awareness"}, {"id": "3410bac6-59f0-4bee-bd7d-542efa81d0bc", "type": "concept", "title": "Railings"}, {"id": "f77da2c9-6fe6-4947-8bd6-425c361fabba", "type": "concept", "title": "Edge protection"}, {"id": "f55377bb-a286-4c83-b960-04f79f8d06af", "type": "concept", "title": "Trip hazards"}, {"id": "a64fea73-9015-4365-86f4-91a3d7b39483", "type": "concept", "title": "Inspection routines"}], "description": "Why learn it: Students learn to think about scenery as a structure people may stand on, lean on, move through, or move around."}]}, {"id": "bd3fee98-e50a-4c43-862a-b63442a5e946", "type": "topic", "title": "Set Painting and Properties", "description": "Paint and props are where technical accuracy meets visual storytelling. Students learn how surface, texture, color, object handling, and prop tracking support character, place, period, and action.", "children": [{"id": "dcc20253-6b2c-455c-9f9d-99c600c78927", "type": "subtopic", "title": "Scenic paint fundamentals", "children": [{"id": "544439cb-8af9-4db2-827e-4bfec76d6b5c", "type": "concept", "title": "Priming"}, {"id": "cc2dfc35-1841-4e34-9d07-dbcf82d138e5", "type": "concept", "title": "Base coats"}, {"id": "75646a34-1368-44dc-ad15-8f25a2ec6e1f", "type": "concept", "title": "Glazes"}, {"id": "e3f0e2d6-76af-4228-9d57-ed6ff39770de", "type": "concept", "title": "Texture"}, {"id": "1f4e622f-ef7e-47c1-85a0-1f9fab0ca52a", "type": "concept", "title": "Aging and distressing"}], "description": "Why learn it: Students learn basic paint materials, surface preparation, and techniques that make scenery read under stage light."}, {"id": "1c2bc1b9-3f8f-4398-963f-8bec27164a97", "type": "subtopic", "title": "Props categories and sourcing", "children": [{"id": "02d5d877-0e44-469b-b2d3-4ad17b742db0", "type": "concept", "title": "Hand props"}, {"id": "9fedbb14-d04c-4ee7-b7d3-6d69be08113b", "type": "concept", "title": "Set dressing"}, {"id": "e577e96a-d14d-4f3e-a02a-ae4307cfcdaf", "type": "concept", "title": "Consumables"}, {"id": "3977123d-ef28-421d-b3b5-574a333c0d8b", "type": "concept", "title": "Borrowing and buying"}, {"id": "75ab84bd-44d1-4eae-ad78-d96df713b322", "type": "concept", "title": "Prop safety"}], "description": "Why learn it: Students distinguish hand props, set props, consumables, rehearsal props, and practical objects."}, {"id": "fb5af607-d937-4f0e-b428-a9f7ab329193", "type": "subtopic", "title": "Props tracking and maintenance", "children": [{"id": "001c867a-8190-4f61-8100-2dc61bbcd790", "type": "concept", "title": "Prop tables"}, {"id": "6dc422f7-8a97-49f3-8fd0-b2b689dd93b9", "type": "concept", "title": "Preset lists"}, {"id": "ad478b86-219c-4fa0-b72b-6b63a21b45cf", "type": "concept", "title": "Handoff tracking"}, {"id": "1a3616ce-3279-433d-804a-39b48ab94c09", "type": "concept", "title": "Food and weapon protocols"}], "description": "Why learn it: Students learn how props are preset, checked, repaired, cleaned, and documented through rehearsal and performance."}]}, {"id": "c4ae67a4-59c7-48ea-9694-c7cf679dd223", "type": "topic", "title": "Lighting Equipment and Hang", "description": "Lighting work requires technical precision, electrical respect, and a designer's sense of visibility, focus, color, and mood. Students learn the equipment and workflow behind a basic hang and focus.", "children": [{"id": "2b542675-3b5f-4eb5-a014-679065769d85", "type": "subtopic", "title": "Lighting instruments and accessories", "children": [{"id": "38e13499-feff-4efe-af13-a1d78662d3c1", "type": "concept", "title": "Ellipsoidals"}, {"id": "a8143a70-f4ad-4a88-8226-d21ac323c06c", "type": "concept", "title": "Fresnels"}, {"id": "230f68a1-ccdc-4bbd-aa4d-2c4fb86deb12", "type": "concept", "title": "PARs"}, {"id": "cb3c053c-4a5e-4ef8-aa93-61cc5cafc48e", "type": "concept", "title": "LED fixtures"}, {"id": "1d71e981-0ad4-468c-82ad-d9c5ff8eb2cc", "type": "concept", "title": "Gobos"}, {"id": "0046a248-d211-458e-b819-3065d3f70014", "type": "concept", "title": "Gel and diffusion"}], "description": "Why learn it: Students identify common fixtures and understand what each can do."}, {"id": "ade08cb9-f6df-435e-96a3-c9be8ca26b68", "type": "subtopic", "title": "Electrics workflow", "children": [{"id": "dbda3288-c2a4-428e-98d5-a205d47deee8", "type": "concept", "title": "Light plot symbols"}, {"id": "9ca784bc-6bf8-4f61-a115-732f1bdbbab8", "type": "concept", "title": "Channel hookup"}, {"id": "ab90b9c5-5056-48e0-9aef-7fff03d08efb", "type": "concept", "title": "DMX basics"}, {"id": "432c4355-159a-4e75-a833-50fceecbd912", "type": "concept", "title": "Cable management"}, {"id": "cb59e38f-1b9e-424b-a6ee-c1c010ae9c5c", "type": "concept", "title": "Focus calls"}], "description": "Why learn it: Students learn how plots become hang positions, circuits, addresses, cable runs, and focus notes."}, {"id": "407a1f11-689b-4ae3-b1f2-efa65d7f19e3", "type": "subtopic", "title": "Electrical and ladder safety", "children": [{"id": "d8058c29-e93a-4605-9302-0058af88eab1", "type": "concept", "title": "Lockout awareness"}, {"id": "883079a4-2387-4481-bfc8-c4d5679ed155", "type": "concept", "title": "Load limits"}, {"id": "3be4b4b6-9c3a-4575-805e-04dadb613833", "type": "concept", "title": "Ladders and lifts"}, {"id": "06ca05c1-907d-4505-ac0a-b8d0f889fc19", "type": "concept", "title": "Hot instruments"}, {"id": "ad656f2c-3951-4a4e-b801-6e507cb6b411", "type": "concept", "title": "Drop prevention"}], "description": "Why learn it: Students build disciplined habits for working around power, height, heat, and overhead equipment."}]}, {"id": "63eab8a6-22b9-4364-8e88-bab4c895f980", "type": "topic", "title": "Sound Equipment and Operation", "description": "Sound work trains students to think about audibility, atmosphere, timing, equipment flow, and operator discipline. The goal is not just pushing play, but understanding how sound systems support storytelling and communication.", "children": [{"id": "db5f3449-5c49-4b64-babc-7643f462789d", "type": "subtopic", "title": "Signal flow", "children": [{"id": "8d1a076e-8b12-4f02-99e0-f90afce55c91", "type": "concept", "title": "Microphones"}, {"id": "7da803c2-d32f-43b5-9963-1b51ac110fa3", "type": "concept", "title": "Cables and connectors"}, {"id": "6775c037-0a30-4b0e-8d2c-5c152bdc533d", "type": "concept", "title": "Mixers"}, {"id": "e14805d7-ce20-41e8-b398-ccf42b6c1ca0", "type": "concept", "title": "Interfaces"}, {"id": "3b42fc06-e9ab-4e23-a2a1-7f1ad97dc9c8", "type": "concept", "title": "Speakers"}], "description": "Why learn it: Students learn how sound moves from source to mixer to processor, amplifier, speaker, recorder, or computer."}, {"id": "2c2ac3e5-f76d-4fec-9a2d-b8e5e3093359", "type": "subtopic", "title": "Playback and reinforcement", "children": [{"id": "bf2be6cb-3a6d-4494-8f0d-3ee8a42bcc09", "type": "concept", "title": "QLab-style cueing"}, {"id": "40cee2a6-9edb-409f-8913-e67393cc0086", "type": "concept", "title": "Levels"}, {"id": "8de82067-b489-4511-9218-424ca1136a88", "type": "concept", "title": "Fades"}, {"id": "54046be1-c1f6-4fe6-95a0-bce19be345e6", "type": "concept", "title": "Monitors"}, {"id": "c9b6bbb9-4d79-4e15-b9cc-b5b0f300d05d", "type": "concept", "title": "Feedback prevention"}], "description": "Why learn it: Students practice basic operation for cues, music, effects, and voice reinforcement."}, {"id": "4bdd1006-675d-4486-8ced-0c1e28c31965", "type": "subtopic", "title": "Sound paperwork and troubleshooting", "children": [{"id": "18f170db-f4b1-4bc3-b089-bd6b3783a23b", "type": "concept", "title": "Cue sheets"}, {"id": "309a54d2-b5ec-43b2-a35a-ab4e09148707", "type": "concept", "title": "Speaker plots"}, {"id": "598adcf9-7fd7-49c1-8809-ec3b23a424ca", "type": "concept", "title": "Battery plans"}, {"id": "1db44bb7-6023-4492-b17f-92d8f082434e", "type": "concept", "title": "No-sound checks"}, {"id": "fa6a4f4b-0d97-41d3-bf9f-5a6ed8a83663", "type": "concept", "title": "Hum and distortion"}], "description": "Why learn it: Students learn how to document cues and solve common problems calmly."}]}, {"id": "58d889b5-ca37-45f1-8f12-306d74cc4247", "type": "topic", "title": "Costume Construction Basics and Wardrobe", "description": "Even in a stagecraft survey, students need enough costume and wardrobe literacy to collaborate across departments. This topic introduces garment handling, basic construction vocabulary, fittings, quick changes, and backstage costume maintenance.", "children": [{"id": "1e483a38-fd47-4352-8f53-1df659e1400b", "type": "subtopic", "title": "Costume shop vocabulary", "children": [{"id": "fcabc12a-ae98-4bde-9be9-dc5149d202a7", "type": "concept", "title": "Measurements"}, {"id": "4243e345-73a8-4825-a5af-3f39575cf9ce", "type": "concept", "title": "Patterns"}, {"id": "1f76afa0-6800-4f9e-b84e-34ff992dacd9", "type": "concept", "title": "Seams and hems"}, {"id": "833b206b-18dc-4b8b-ac6b-276afd23d9e0", "type": "concept", "title": "Closures"}, {"id": "bdd3794d-fbea-4378-8fd9-e38a32e03905", "type": "concept", "title": "Alterations"}], "description": "Why learn it: Students learn the basic terms needed to communicate with costume designers, shop staff, and wardrobe crew."}, {"id": "740cb6d2-bf72-4d7f-a019-446902aeb7ec", "type": "subtopic", "title": "Wardrobe crew operations", "children": [{"id": "6f32d046-5a39-45e8-b62d-62a3bae7f65d", "type": "concept", "title": "Presets"}, {"id": "0734ca3c-2606-446e-b525-69366b3ebbf2", "type": "concept", "title": "Quick changes"}, {"id": "d34cf564-d917-4514-85a3-280b0a05f0a1", "type": "concept", "title": "Laundry"}, {"id": "144c690c-114b-4cb5-afac-2931e841b764", "type": "concept", "title": "Repairs"}, {"id": "1ed23790-c375-4101-8554-42c62b0c7c11", "type": "concept", "title": "Show tracks"}], "description": "Why learn it: Students learn backstage costume support for rehearsals, dress rehearsals, and performances."}, {"id": "ffe290de-e3bc-434e-8330-4103b05b5ee0", "type": "subtopic", "title": "Costume safety and performer care", "children": [{"id": "bc09f8eb-c2be-41c0-8f7b-830237672202", "type": "concept", "title": "Footwear checks"}, {"id": "08be55f6-f84f-4290-8700-42847bc40037", "type": "concept", "title": "Mobility"}, {"id": "89adf7a4-55bc-456a-b77e-b3ab082f4340", "type": "concept", "title": "Modesty garments"}, {"id": "7c9e72b5-5123-4961-8b48-10a15b50e007", "type": "concept", "title": "Heat and hydration"}, {"id": "177a655a-4d56-4523-9f8f-e947586db7df", "type": "concept", "title": "Consent and privacy"}], "description": "Why learn it: Students learn how clothing, footwear, movement, heat, intimacy, and identity affect safe wardrobe practice."}]}, {"id": "6ea3762e-20ac-4242-a6e8-10f35393ff13", "type": "topic", "title": "Stage Rigging and Safety", "description": "Rigging is a high-consequence technical area. Introductory students should learn vocabulary, hazard recognition, communication protocols, and when work must be handled by trained specialists.", "children": [{"id": "515f1910-2bea-4c81-a4bf-b575e5e46ce5", "type": "subtopic", "title": "Rigging systems and vocabulary", "children": [{"id": "61a3362c-dcd4-4e95-a262-5ae31d07115a", "type": "concept", "title": "Line sets"}, {"id": "f444e7ac-645e-434e-a443-e7a7e4a4ed5e", "type": "concept", "title": "Battens"}, {"id": "8b3e25b8-82ee-4086-b007-0b6d0ddf1e66", "type": "concept", "title": "Counterweight systems"}, {"id": "6a46728a-fce6-4d84-afc9-e356771db095", "type": "concept", "title": "Dead-hung elements"}, {"id": "5bce037d-9b2b-4e24-9c05-55930cab244c", "type": "concept", "title": "Fly rail communication"}], "description": "Why learn it: Students learn the basic language of overhead systems without being asked to perform advanced rigging beyond training."}, {"id": "60d2b335-6377-4423-b8a8-c84d33e55e14", "type": "subtopic", "title": "Loads and hardware awareness", "children": [{"id": "dc49d1d2-1dbd-49cd-ba58-829885df3694", "type": "concept", "title": "Working load limit"}, {"id": "ddfb2cb9-ca75-41cf-baa9-5b6dc125c90a", "type": "concept", "title": "Shackles and spansets"}, {"id": "1a27cf88-1528-4486-9e9d-01c0985ad9d0", "type": "concept", "title": "Aircraft cable"}, {"id": "867f6db7-6fb1-468c-8026-76e98271801e", "type": "concept", "title": "Soft goods"}, {"id": "eaff52ef-a35a-4348-aea1-2d735446d8c0", "type": "concept", "title": "Inspection tags"}], "description": "Why learn it: Students learn why weight, attachment points, ratings, and inspection matter."}, {"id": "1427f6c3-e43f-4870-9d7c-ad6e17f7b8b1", "type": "subtopic", "title": "Safe operating protocols", "children": [{"id": "4c10d0dd-2890-4270-a645-3dd2b5433658", "type": "concept", "title": "Clear calls"}, {"id": "11329760-2d63-423f-b067-1266cc02a9f9", "type": "concept", "title": "Rail discipline"}, {"id": "051d0b2c-d8d1-47b1-a1f1-4ecdad23d3f8", "type": "concept", "title": "Exclusion zones"}, {"id": "a511a41e-659d-47c4-8c17-887e75a3167c", "type": "concept", "title": "Emergency stops"}, {"id": "79c6866d-ba73-40e9-81e1-ec09beeb5d00", "type": "concept", "title": "Qualified supervision"}], "description": "Why learn it: Students practice the communication habits that prevent accidents around moving scenery and overhead work."}]}, {"id": "4b4200fe-f9d8-4ab2-9b4b-22d6d6aeb8c8", "type": "topic", "title": "Running Crew Responsibilities", "description": "Running crew work teaches precision, consistency, communication, and accountability. Students learn how backstage labor keeps a show safe and repeatable from preshow through strike.", "children": [{"id": "70eedc7d-1c15-4ed0-a8d9-34555acf33c5", "type": "subtopic", "title": "Crew roles and tracks", "children": [{"id": "b4daac4f-89da-4d55-91ad-79da15dd6b22", "type": "concept", "title": "Deck tracks"}, {"id": "054b6620-f4b5-4d44-a1e0-b5aff6f1abe0", "type": "concept", "title": "Shift plots"}, {"id": "86269e0c-df9a-4209-bf67-aaf571d14384", "type": "concept", "title": "Props tracks"}, {"id": "44c0058f-bab8-4b6e-bd37-358dda15599f", "type": "concept", "title": "Wardrobe tracks"}, {"id": "97767f51-666e-4831-935b-14bf08cd005f", "type": "concept", "title": "Operator positions"}], "description": "Why learn it: Students learn the difference between deck crew, props crew, wardrobe, electrics, sound, fly crew, and assistant stage management support."}, {"id": "4364f260-a78c-4f8c-a3ab-9a701d117726", "type": "subtopic", "title": "Backstage communication", "children": [{"id": "cb65ac7f-0088-4fb3-8cf1-95fea44a31f9", "type": "concept", "title": "Headset etiquette"}, {"id": "310adbfb-d909-4428-b477-a0a7c86f3d0a", "type": "concept", "title": "Hand signals"}, {"id": "a4f48f99-fb2c-4665-99df-5f47eade8c21", "type": "concept", "title": "Cue ligh